BITS: int = 8


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping high bits to the low end.

    x is an int in 0..255 and k is an int in 0..7. The result is in 0..255.
    """
    x &= 0xFF
    k %= BITS
    return ((x << k) | (x >> (BITS - k))) & 0xFF


def test_rotl8_zero_shift_is_identity() -> None:
    assert rotl8(0b10110010, 0) == 0b10110010
    assert rotl8(0, 0) == 0


def test_rotl8_single_bit_moves_left() -> None:
    assert rotl8(0b00000001, 1) == 0b00000010
    assert rotl8(0b00000001, 7) == 0b10000000


def test_rotl8_high_bit_wraps_to_low() -> None:
    assert rotl8(0b10000000, 1) == 0b00000001
    assert rotl8(0b10000001, 1) == 0b00000011


def test_rotl8_all_ones_is_fixed() -> None:
    for k in range(BITS):
        assert rotl8(0xFF, k) == 0xFF


def test_rotl8_result_stays_in_byte_range() -> None:
    for x in range(256):
        for k in range(BITS):
            assert 0 <= rotl8(x, k) <= 255


def test_rotl8_full_rotation_composes() -> None:
    assert rotl8(rotl8(0x12, 3), 5) == 0x12
    assert rotl8(0x9C, 4) == rotl8(rotl8(0x9C, 2), 2)
